import {
  existsSync,
  readFileSync,
  writeFileSync,
  renameSync,
  mkdirSync,
} from "node:fs";
import { dirname, join } from "node:path";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type Status = "open" | "done";

interface Task {
  id: number;
  title: string;
  status: Status;
  tags: string[];
  due: string | null; // YYYY-MM-DD or null
  createdAt: string; // ISO timestamp
  completedAt: string | null; // ISO timestamp
}

interface DB {
  tasks: Task[];
  nextId: number;
}

// ---------------------------------------------------------------------------
// Storage
// ---------------------------------------------------------------------------

function dbPath(): string {
  const env = process.env.TASKBOARD_FILE;
  return env && env.length > 0 ? env : ".taskboard.json";
}

function loadDB(path: string): DB {
  if (!existsSync(path)) {
    return { tasks: [], nextId: 1 };
  }
  let raw: string;
  try {
    raw = readFileSync(path, "utf8");
  } catch {
    throw new Error(`cannot read database file: ${path}`);
  }
  let data: unknown;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new Error(`malformed database: ${path} is not valid JSON`);
  }
  validateDB(data, path);
  return data as DB;
}

function validateDB(data: unknown, path: string): void {
  if (typeof data !== "object" || data === null || Array.isArray(data)) {
    throw new Error(`malformed database: ${path} expected an object`);
  }
  const d = data as Record<string, unknown>;
  if (!Array.isArray(d.tasks)) {
    throw new Error(`malformed database: ${path} missing tasks array`);
  }
  if (
    typeof d.nextId !== "number" ||
    !Number.isInteger(d.nextId) ||
    d.nextId < 1
  ) {
    throw new Error(`malformed database: ${path} nextId must be a positive integer`);
  }
  for (let i = 0; i < d.tasks.length; i++) {
    const t = d.tasks[i];
    if (typeof t !== "object" || t === null) {
      throw new Error(`malformed database: ${path} task ${i} is invalid`);
    }
    const task = t as Record<string, unknown>;
    if (typeof task.id !== "number" || !Number.isInteger(task.id)) {
      throw new Error(`malformed database: ${path} task ${i} has invalid id`);
    }
    if (typeof task.title !== "string") {
      throw new Error(`malformed database: ${path} task ${i} has invalid title`);
    }
    if (task.status !== "open" && task.status !== "done") {
      throw new Error(`malformed database: ${path} task ${i} has invalid status`);
    }
    if (!Array.isArray(task.tags)) {
      throw new Error(`malformed database: ${path} task ${i} has invalid tags`);
    }
    if (task.due !== null && typeof task.due !== "string") {
      throw new Error(`malformed database: ${path} task ${i} has invalid due`);
    }
    if (typeof task.createdAt !== "string") {
      throw new Error(`malformed database: ${path} task ${i} has invalid createdAt`);
    }
    if (task.completedAt !== null && typeof task.completedAt !== "string") {
      throw new Error(`malformed database: ${path} task ${i} has invalid completedAt`);
    }
  }
}

function saveDB(path: string, db: DB): void {
  const dir = dirname(path);
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
  const tmp = join(dir, `.${process.pid}.${Date.now()}.taskboard.tmp`);
  writeFileSync(tmp, JSON.stringify(db, null, 2) + "\n", "utf8");
  renameSync(tmp, path);
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function daysInMonth(y: number, m: number): number {
  const dim = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  let d = dim[m - 1];
  if (m === 2 && ((y % 4 === 0 && y % 100 !== 0) || y % 400 === 0)) d = 29;
  return d;
}

function isValidDate(s: string): boolean {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return false;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  if (mo < 1 || mo > 12) return false;
  if (d < 1 || d > daysInMonth(y, mo)) return false;
  return true;
}

function todayLocal(): string {
  const n = new Date();
  const y = n.getFullYear();
  const m = String(n.getMonth() + 1).padStart(2, "0");
  const d = String(n.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function normalizeTags(raw: string): string[] {
  const parts = raw
    .split(",")
    .map((p) => p.trim().toLowerCase())
    .filter((p) => p !== "");
  const seen = new Set<string>();
  const out: string[] = [];
  for (const p of parts) {
    if (!seen.has(p)) {
      seen.add(p);
      out.push(p);
    }
  }
  return out;
}

function parseId(s: string): number {
  const n = Number(s);
  if (!Number.isInteger(n)) {
    throw new Error(`invalid task id: ${s}`);
  }
  return n;
}

// ---------------------------------------------------------------------------
// Argument parsing
// ---------------------------------------------------------------------------

interface Parsed {
  positional: string[];
  flags: Record<string, string>;
}

const KNOWN_FLAGS: Record<string, Set<string>> = {
  add: new Set(["--title", "--tags", "--due"]),
  list: new Set(["--status", "--tag", "--overdue"]),
  done: new Set<string>(),
  delete: new Set<string>(),
  stats: new Set<string>(),
};

function parseArgs(argv: string[], known: Set<string>): Parsed {
  const positional: string[] = [];
  const flags: Record<string, string> = {};
  let i = 0;
  while (i < argv.length) {
    const a = argv[i];
    if (a === "--") {
      positional.push(...argv.slice(i + 1));
      break;
    }
    if (a.startsWith("--")) {
      let name: string;
      let value: string | undefined;
      if (a.includes("=")) {
        const eq = a.indexOf("=");
        name = a.slice(0, eq);
        value = a.slice(eq + 1);
      } else {
        name = a;
        if (i + 1 < argv.length) {
          value = argv[i + 1];
          i++;
        } else {
          value = undefined;
        }
      }
      if (!known.has(name)) {
        throw new Error(`unknown flag: ${name}`);
      }
      if (value === undefined) {
        throw new Error(`flag ${name} requires a value`);
      }
      flags[name] = value;
    } else {
      positional.push(a);
    }
    i++;
  }
  return { positional, flags };
}

// ---------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------

function printJSON(v: unknown): void {
  process.stdout.write(JSON.stringify(v, null, 2) + "\n");
}

// ---------------------------------------------------------------------------
// Commands
// ---------------------------------------------------------------------------

function cmdAdd(flags: Record<string, string>): Task {
  if (flags["--title"] === undefined) {
    throw new Error("add requires --title TEXT");
  }
  const title = flags["--title"];
  if (title.trim() === "") {
    throw new Error("title must not be empty");
  }
  let tags: string[] = [];
  if (flags["--tags"] !== undefined) {
    tags = normalizeTags(flags["--tags"]);
  }
  let due: string | null = null;
  if (flags["--due"] !== undefined) {
    if (!isValidDate(flags["--due"])) {
      throw new Error(`impossible due date: ${flags["--due"]}`);
    }
    due = flags["--due"];
  }
  const path = dbPath();
  const db = loadDB(path);
  const task: Task = {
    id: db.nextId,
    title,
    status: "open",
    tags,
    due,
    createdAt: new Date().toISOString(),
    completedAt: null,
  };
  db.tasks.push(task);
  db.nextId += 1;
  saveDB(path, db);
  return task;
}

function cmdList(flags: Record<string, string>): Task[] {
  const path = dbPath();
  const db = loadDB(path);
  let tasks = db.tasks.slice();
  if (flags["--status"] !== undefined) {
    const st = flags["--status"];
    if (st !== "open" && st !== "done") {
      throw new Error(`invalid --status: ${st} (expected open|done)`);
    }
    tasks = tasks.filter((t) => t.status === st);
  }
  if (flags["--tag"] !== undefined) {
    const tag = flags["--tag"].trim().toLowerCase();
    tasks = tasks.filter((t) => t.tags.includes(tag));
  }
  if (flags["--overdue"] !== undefined) {
    const d = flags["--overdue"];
    if (!isValidDate(d)) {
      throw new Error(`impossible --overdue date: ${d}`);
    }
    tasks = tasks.filter(
      (t) => t.status === "open" && t.due !== null && t.due < d,
    );
  }
  tasks.sort((a, b) => a.id - b.id);
  return tasks;
}

function cmdDone(positional: string[]): Task {
  if (positional.length !== 1) {
    throw new Error("done requires exactly one task id");
  }
  const id = parseId(positional[0]);
  const path = dbPath();
  const db = loadDB(path);
  const task = db.tasks.find((t) => t.id === id);
  if (!task) {
    throw new Error(`no task with id ${id}`);
  }
  if (task.status !== "done") {
    task.status = "done";
    task.completedAt = new Date().toISOString();
    saveDB(path, db);
  }
  return task;
}

function cmdDelete(positional: string[]): { id: number; deleted: boolean } {
  if (positional.length !== 1) {
    throw new Error("delete requires exactly one task id");
  }
  const id = parseId(positional[0]);
  const path = dbPath();
  const db = loadDB(path);
  const idx = db.tasks.findIndex((t) => t.id === id);
  if (idx === -1) {
    throw new Error(`no task with id ${id}`);
  }
  db.tasks.splice(idx, 1);
  saveDB(path, db);
  return { id, deleted: true };
}

function cmdStats(positional: string[], flags: Record<string, string>): {
  total: number;
  open: number;
  done: number;
  overdue: number;
} {
  if (positional.length > 0 || Object.keys(flags).length > 0) {
    throw new Error("stats takes no arguments");
  }
  const path = dbPath();
  const db = loadDB(path);
  const today = todayLocal();
  let open = 0;
  let done = 0;
  let overdue = 0;
  for (const t of db.tasks) {
    if (t.status === "open") {
      open++;
      if (t.due !== null && t.due < today) overdue++;
    } else {
      done++;
    }
  }
  return { total: db.tasks.length, open, done, overdue };
}

// ---------------------------------------------------------------------------
// Dispatch
// ---------------------------------------------------------------------------

function dispatch(): void {
  const argv = process.argv.slice(2);
  if (argv.length === 0) {
    throw new Error(
      "no command given; expected one of: add, list, done, delete, stats",
    );
  }
  const command = argv[0];
  const rest = argv.slice(1);
  switch (command) {
    case "add": {
      const { flags } = parseArgs(rest, KNOWN_FLAGS.add);
      printJSON(cmdAdd(flags));
      break;
    }
    case "list": {
      const { flags } = parseArgs(rest, KNOWN_FLAGS.list);
      printJSON(cmdList(flags));
      break;
    }
    case "done": {
      const { positional, flags } = parseArgs(rest, KNOWN_FLAGS.done);
      if (Object.keys(flags).length > 0) {
        throw new Error("done does not accept flags");
      }
      printJSON(cmdDone(positional));
      break;
    }
    case "delete": {
      const { positional, flags } = parseArgs(rest, KNOWN_FLAGS.delete);
      if (Object.keys(flags).length > 0) {
        throw new Error("delete does not accept flags");
      }
      printJSON(cmdDelete(positional));
      break;
    }
    case "stats": {
      const { positional, flags } = parseArgs(rest, KNOWN_FLAGS.stats);
      printJSON(cmdStats(positional, flags));
      break;
    }
    default:
      throw new Error(
        `unknown command: ${command} (expected add|list|done|delete|stats)`,
      );
  }
}

function main(): void {
  try {
    dispatch();
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    process.stderr.write(`error: ${msg}\n`);
    process.exit(1);
  }
}

main();

